/* eslint-disable prefer-const */
"use client";
import { FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useAuth } from "../../../components/auth/AuthProvider";
import { Icon } from "../../../components/Icon";
import { ManufacturerCatalogField } from "../../../components/ManufacturerCatalogField";
import { PmtaCalculationPanel } from "../../../components/PmtaCalculationPanel";
import { useSystem } from "../../../components/system/SystemProvider";
import { Answer, Device, emptyInspectionData, Evidence, InspectionTechnicalData, normalizeInspectionData, Reading } from "../../../lib/inspection-model";
import { calculatePmta } from "../../../lib/pmta";
import { addCalendarYears } from "../../../lib/calendar";
import { calculateVolume, VolumeGeometry } from "../../../lib/volume";
import { validateInspectionConsistency } from "../../../lib/inspection-validation";

const steps=["Escopo","Equipamento","Documentação","Exames e ensaios","Dispositivos","Conclusão","Responsabilidade"];
const answers:[Answer,string][]=[["COMPLIANT","Conforme"],["NON_COMPLIANT","Não conforme"],["NOT_APPLICABLE","Não aplicável"],["NOT_VERIFIED","Não verificado"]];
const pressureUnits=["bar","psi","kPa","MPa"] as const;
const evidenceTypes=[['GENERAL','Foto geral'],['IDENTIFICATION_PLATE','Placa de identificação'],['COMPONENT','Componente relevante'],['NON_CONFORMITY','Não conformidade'],['DOCUMENT','Documento'],['OTHER','Outra evidência']] as const;
const docLabels:Record<string,string>={identificationPlate:"Placa de identificação legível e coerente",categoryMarking:"TAG e categoria visíveis",safetyRecord:"Registro de Segurança atualizado",installationProject:"Projeto de instalação",operationManual:"Manual/instruções de operação",previousReports:"Relatórios e recomendações anteriores",alterationRepairProject:"Projeto de Alteração ou Reparo, quando aplicável",operatorTraining:"Capacitação dos operadores"};
class InspectionValidationError extends Error { constructor(message:string,readonly step:number,readonly targetId?:string){super(message)} }
function Field({label,children,wide=false}:{label:string;children:ReactNode;wide?:boolean}){return <label className={wide?"inspectionField wide":"inspectionField"}><span>{label}</span>{children}</label>}
function VolumePanel({value,onChange,onError}:{value:InspectionTechnicalData;onChange:React.Dispatch<React.SetStateAction<InspectionTechnicalData>>;onError:(v:string)=>void}){const details=value.volumeDetails||{unit:"L" as const};const calc=details.calculation;const update=(patch:Partial<typeof details>)=>onChange(current=>({...current,volumeDetails:{...(current.volumeDetails||{unit:"L"}),...patch}}));const run=()=>{try{const result=calculateVolume({geometry:(calc?.geometry||"CYLINDER_FLAT") as VolumeGeometry,diameterM:calc?.diameterM||0,straightLengthM:calc?.straightLengthM});onChange(current=>({...current,identification:{...current.identification,volume:String(result.resultM3)},volumeDetails:{unit:"M3",calculation:result}}));onError("")}catch(e){onError(e instanceof Error?e.message:"Medidas inválidas")}};return <section className="periodicityPanel"><h3>Volume / capacidade</h3><div className="inspectionGrid"><Field label="Valor numérico"><input type="number" min="0" step="0.001" value={value.identification.volume} onChange={e=>onChange(current=>({...current,identification:{...current.identification,volume:e.target.value}}))}/></Field><Field label="Unidade"><select value={details.unit} onChange={e=>update({unit:e.target.value as "L"|"M3"|"T"})}><option value="L">L</option><option value="M3">m³</option><option value="T">t (massa)</option></select></Field>{details.unit==="T"&&<Field label="Densidade (kg/m³), obrigatória para converter"><input type="number" min="0.001" value={details.densityKgM3||""} onChange={e=>update({densityKgM3:e.target.value})}/></Field>}<Field label="Calcular pelas medidas"><select value={calc?.geometry||"CYLINDER_FLAT"} onChange={e=>update({calculation:{geometry:e.target.value as VolumeGeometry,diameterM:calc?.diameterM||0,straightLengthM:calc?.straightLengthM,resultM3:0,memory:""}})}><option value="CYLINDER_FLAT">Cilindro com tampos planos</option><option value="CYLINDER_HEMISPHERICAL">Cilindro com dois tampos hemisféricos</option><option value="SPHERE">Esfera</option></select></Field><Field label="Diâmetro interno (m)"><input type="number" min="0" step="0.001" value={calc?.diameterM||""} onChange={e=>update({calculation:{geometry:calc?.geometry||"CYLINDER_FLAT",diameterM:Number(e.target.value),straightLengthM:calc?.straightLengthM,resultM3:0,memory:""}})}/></Field>{calc?.geometry!=="SPHERE"&&<Field label="Comprimento cilíndrico reto (m)"><input type="number" min="0" step="0.001" value={calc?.straightLengthM||""} onChange={e=>update({calculation:{geometry:calc?.geometry||"CYLINDER_FLAT",diameterM:calc?.diameterM||0,straightLengthM:Number(e.target.value),resultM3:0,memory:""}})}/></Field>}</div><button type="button" className="secondaryBtn" onClick={run}>Calcular volume</button>{calc?.memory&&<p className="technicalNote">Memória: {calc.memory}</p>}</section>}
function EvidenceUploader({busy,onUpload}:{busy:boolean;onUpload:(file:File,type:Evidence["type"],title:string,description:string)=>void}){const [type,setType]=useState<Evidence["type"]>("GENERAL");const [title,setTitle]=useState("");const [description,setDescription]=useState("");return <div className="evidenceUploader"><Field label="Tipo"><select value={type} onChange={e=>setType(e.target.value as Evidence["type"])}>{evidenceTypes.map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></Field><Field label="Legenda"><input value={title} maxLength={120} onChange={e=>setTitle(e.target.value)} placeholder="Ex.: Vista geral do vaso"/></Field><Field label="Descrição"><input value={description} maxLength={500} onChange={e=>setDescription(e.target.value)} placeholder="Local, componente ou condição observada"/></Field><label className="uploadButton">{busy?"Enviando…":"Selecionar arquivo"}<input type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf" disabled={busy} onChange={e=>{for(const file of Array.from(e.target.files||[]))onUpload(file,type,title,description);e.target.value=""}}/></label></div>}
const text=(value:string,onChange:(v:string)=>void,required=false)=><input value={value} required={required} onChange={e=>onChange(e.target.value)}/>;
type InspectionDraft={id:string;equipmentId:string;status:string;sourceReportId?:string|null;technicalData:InspectionTechnicalData|null;evidence:Evidence[]};
type CatalogItem={id:string;name:string};
async function prepareEvidence(file:File){if(file.type==="application/pdf")return {blob:file,mimeType:file.type,fileName:file.name};const bitmap=await createImageBitmap(file);const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext("2d");if(!context)throw new Error("Não foi possível preparar a imagem.");context.fillStyle="#fff";context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,"image/jpeg",.84));if(!blob)throw new Error("Não foi possível compactar a imagem.");return {blob,mimeType:"image/jpeg",fileName:file.name.replace(/\.[^.]+$/,"")+".jpg"}}

export default function Inspection(){
 const {companies,equipment,companyFilter,setCompanyFilter,refreshInspections}=useSystem(); const {request}=useAuth(); const router=useRouter(); const [deviceTypes,setDeviceTypes]=useState<CatalogItem[]>([]);const [newDeviceType,setNewDeviceType]=useState("");const [deviceTypeIndex,setDeviceTypeIndex]=useState<number|null>(null);const [deviceTypeError,setDeviceTypeError]=useState("");
 const available=equipment.filter(e=>companyFilter==="all"||e.companyId===companyFilter); const filteredCompany=companies.find(c=>c.id===companyFilter); const [selectedState,setSelected]=useState(""); const selected=available.some(item=>item.id===selectedState)?selectedState:available[0]?.id||""; const [step,setStep]=useState(0); const [data,setData]=useState<InspectionTechnicalData>(emptyInspectionData); const [busy,setBusy]=useState(false); const [error,setError]=useState(""); const [validationTarget,setValidationTarget]=useState<string|null>(null); const [saved,setSaved]=useState(false); const [draftId,setDraftId]=useState<string|null>(null); const [draftStarted,setDraftStarted]=useState(false); const [sourceReportId,setSourceReportId]=useState<string|null>(null); const canvasRef=useRef<HTMLCanvasElement>(null); const errorRef=useRef<HTMLParagraphElement>(null); const drawing=useRef(false); const [signed,setSigned]=useState(false);
 const asset=available.find(e=>e.id===selected); const company=companies.find(c=>c.id===asset?.companyId); const upd=<K extends keyof InspectionTechnicalData>(key:K,value:InspectionTechnicalData[K])=>setData(d=>({...d,[key]:value})); const setId=(key:keyof InspectionTechnicalData["identification"],value:string|boolean)=>upd("identification",{...data.identification,[key]:value});
 const deadlineBase=data.scope.finishedAt||data.scope.startedAt||new Date().toISOString().slice(0,10); const setDeadlinePeriod=(periodKey:"externalPeriodYears"|"internalPeriodYears"|"hydrostaticPeriodYears",dateKey:"nextExternal"|"nextInternal"|"nextHydrostatic",years:number)=>upd("deadlines",{...data.deadlines,[periodKey]:years,[dateKey]:years?addCalendarYears(deadlineBase,years):""});
 useEffect(()=>{let cancelled=false;const id=new URLSearchParams(window.location.search).get("draft");if(!id)return()=>{cancelled=true};void request<InspectionDraft>(`/inspections/${id}`).then(async detail=>{if(detail.status!=="IN_PROGRESS")throw new Error("Este registro não é mais um rascunho.");const evidence=await Promise.all((detail.evidence||[]).map(async item=>{try{const image=await request<{dataUrl:string}>(`/inspections/${id}/evidence/${item.id}`);return {...item,dataUrl:image.dataUrl}}catch{return item}}));if(!cancelled){setCompanyFilter("all");setSelected(detail.equipmentId);setDraftId(id);setDraftStarted(true);setSourceReportId(detail.sourceReportId||null);setData(detail.technicalData?{...normalizeInspectionData(detail.technicalData),evidence}:{...emptyInspectionData(),evidence})}}).catch(x=>{if(!cancelled)setError(x instanceof Error?x.message:"Não foi possível recuperar o rascunho")});return()=>{cancelled=true}},[request,setCompanyFilter]);
 useEffect(()=>{void request<CatalogItem[]>("/catalogs?kind=DEVICE_TYPE").then(setDeviceTypes).catch(()=>setDeviceTypes([]))},[request]);
 const openDeviceType=(index:number)=>{setDeviceTypeIndex(index);setNewDeviceType("");setDeviceTypeError("")};
 const closeDeviceType=()=>{setDeviceTypeIndex(null);setNewDeviceType("");setDeviceTypeError("")};
 const selectDeviceType=(index:number,kind:string)=>upd("devices",data.devices.map((device,n)=>n===index?{...device,kind}:device));
 const createDeviceType=async(event:FormEvent)=>{event.preventDefault();if(deviceTypeIndex===null)return;const name=newDeviceType.trim().replace(/\s+/g," ");if(!name){setDeviceTypeError("Informe o nome do novo tipo.");return}const normalized=name.toLocaleLowerCase("pt-BR");const baseTypes=[["PSV","PSV / válvula de segurança"],["PRESSURE_GAUGE","Manômetro / medidor de pressão"]] as const;const base=baseTypes.find(([value,label])=>value.toLocaleLowerCase("pt-BR")===normalized||label.toLocaleLowerCase("pt-BR")===normalized);if(base){selectDeviceType(deviceTypeIndex,base[0]);closeDeviceType();return}const existing=deviceTypes.find(item=>item.name.trim().toLocaleLowerCase("pt-BR")===normalized);if(existing){selectDeviceType(deviceTypeIndex,existing.name);closeDeviceType();return}setBusy(true);setDeviceTypeError("");try{const item=await request<CatalogItem>("/catalogs",{method:"POST",body:JSON.stringify({kind:"DEVICE_TYPE",name})});setDeviceTypes(current=>[...current,item].sort((a,b)=>a.name.localeCompare(b.name)));selectDeviceType(deviceTypeIndex,item.name);closeDeviceType()}catch(cause){setDeviceTypeError(cause instanceof Error?cause.message:"Não foi possível salvar o tipo")}finally{setBusy(false)}};
 useEffect(()=>{if(!validationTarget)return;const frame=requestAnimationFrame(()=>{const target=document.getElementById(validationTarget);target?.focus({preventScroll:true});target?.scrollIntoView({behavior:"smooth",block:"center"});setValidationTarget(null)});return()=>cancelAnimationFrame(frame)},[step,validationTarget]);
 const chooseEquipment=(id:string)=>{setSelected(id);setDraftId(null);setDraftStarted(false);setSourceReportId(null);setData(emptyInspectionData());setSaved(false);setError("")};
 const examinations=data.scope.examinations; const has=(v:string)=>examinations.includes(v); const toggleExam=(v:string)=>upd("scope",{...data.scope,examinations:has(v)?examinations.filter(x=>x!==v):[...examinations,v]});
 const checklist=useMemo(()=>Object.entries(data.documentation).map(([code,result])=>({code,label:docLabels[code],result})),[data.documentation]); const fieldData=()=>({checklist,measurements:data.readings.filter(r=>r.value!=="").map(r=>({key:r.key,name:`${r.point}${r.component?` - ${r.component}`:""}`,value:Number(r.value.replace(",",".")),unit:r.unit||"mm",reference:r.minimum||undefined,observation:r.observation||undefined})),anomalies:(data.nonConformities||[]).map(item=>({description:item.description,severity:item.criticality,status:item.status,correctiveAction:item.correctiveAction,dueDate:item.dueDate||undefined}))});
 const validateConclusionStep=()=>{const consistency=validateInspectionConsistency(data).find(item=>item.blocking);if(consistency)throw new InspectionValidationError(consistency.message,consistency.code.includes("PMTA")||consistency.code.includes("DEVICE")?4:5);if(!data.scope.finishedAt)throw new InspectionValidationError("Informe a data de conclusão.",5,"inspection-finished-at");if(!data.conclusion.trim())throw new InspectionValidationError("Informe o parecer conclusivo.",5,"inspection-conclusion");if(!data.deadlines.nextExternal&&!data.deadlines.nextInternal)throw new InspectionValidationError("Informe ao menos um prazo de próxima inspeção.",5,"inspection-next-external")};
 const validate=()=>{if(!selected)throw new InspectionValidationError("Selecione um equipamento.",0);if(!data.scope.examinations.length)throw new InspectionValidationError("Selecione ao menos um exame ou ensaio.",0);if(data.pmtaCalculation?.mode==="CALCULATED"){if(!/^ASME VIII Div\. 1/i.test(data.identification.constructionCode))throw new InspectionValidationError("Selecione ASME VIII Div. 1 como código de construção para calcular PMTA.",1);if(!data.pmtaCalculation.edition?.trim())throw new InspectionValidationError("Informe a edição do código no cálculo de PMTA.",1);const pmta=calculatePmta(data.pmtaCalculation),recorded=Number(data.identification.pmta);if(!Number.isFinite(recorded)||Math.abs(recorded-pmta.adoptedResultBar)>.01)throw new InspectionValidationError("O valor de PMTA deve corresponder ao resultado calculado.",1)}validateConclusionStep();if(company?.measurementPhotoRequired){const missing=data.readings.filter(r=>r.value!==""&&!data.evidence.some(e=>e.measurementKey===r.key));if(missing.length)throw new InspectionValidationError(`Fotos obrigatórias pendentes nos pontos: ${missing.map(r=>r.point||"Sem identificação").join(", ")}.`,3)}if(!signed)throw new InspectionValidationError("A assinatura do responsável técnico é obrigatória para concluir.",6)};
 const showValidationError=(validationError:InspectionValidationError)=>{setStep(validationError.step);setError(validationError.message);setValidationTarget(validationError.targetId||null);if(!validationError.targetId)requestAnimationFrame(()=>errorRef.current?.focus())};
 const continueFlow=()=>{setError("");try{if(step===5)validateConclusionStep();setStep(current=>current+1)}catch(x){if(x instanceof InspectionValidationError)showValidationError(x);else setError(x instanceof Error?x.message:"Não foi possível continuar")}};
 const persist=async(complete:boolean)=>{setBusy(true);setError("");try{if(complete)validate();let id=draftId;let started=draftStarted;if(!id){const created=await request<{id:string}>("/inspections",{method:"POST",body:JSON.stringify({equipmentId:selected,type:data.scope.inspectionType,scheduledAt:new Date().toISOString()})});id=created.id;setDraftId(id)}if(!started){await request(`/inspections/${id}/transitions`,{method:"POST",body:JSON.stringify({status:"IN_PROGRESS"})});started=true;setDraftStarted(true)}await request(`/inspections/${id}/field-data`,{method:"PUT",body:JSON.stringify(fieldData())});const signatureData=canvasRef.current?.toDataURL("image/png");const technicalData={...data,evidence:data.evidence.map(({id,type,title,description,fileName,mimeType,size,sha256,capturedAt,measurementKey})=>({id,type,title,description,fileName,mimeType,size,sha256,capturedAt,measurementKey}))};await request(`/inspections/${id}`,{method:"PATCH",body:JSON.stringify({performedAt:complete?new Date(`${data.scope.finishedAt}T12:00:00`).toISOString():undefined,signatureData:complete?signatureData:undefined,technicalData,technicalInformation:`Modelo técnico v${data.schemaVersion}`,observations:data.examinations.externalNotes,recommendations:data.recommendations,conclusion:data.conclusion||undefined,result:complete?data.result:undefined})});if(complete){await request(`/inspections/${id}/transitions`,{method:"POST",body:JSON.stringify({status:"COMPLETED"})});await refreshInspections();router.push("/app/laudos")}else{await refreshInspections();router.push(`/app/laudos?draft=${id}`)}}catch(x){if(x instanceof InspectionValidationError)showValidationError(x);else{setError(x instanceof Error?x.message:"Não foi possível salvar a inspeção");requestAnimationFrame(()=>errorRef.current?.focus())}}finally{setBusy(false)}};
 const uploadEvidence=async(file:File,type:Evidence["type"],title:string,description:string,measurementKey?:string)=>{if(!selected){setError("Selecione um equipamento.");return}if(!file.type.match(/^(image\/(jpeg|png|webp)|application\/pdf)$/)){setError("Use JPEG, PNG, WebP ou PDF.");return}setBusy(true);setError("");try{let id=draftId;let started=draftStarted;if(!id){const created=await request<{id:string}>("/inspections",{method:"POST",body:JSON.stringify({equipmentId:selected,type:data.scope.inspectionType,scheduledAt:new Date().toISOString()})});id=created.id;setDraftId(id)}if(!started){await request(`/inspections/${id}/transitions`,{method:"POST",body:JSON.stringify({status:"IN_PROGRESS"})});setDraftStarted(true)}await request(`/inspections/${id}/field-data`,{method:"PUT",body:JSON.stringify(fieldData())});const prepared=await prepareEvidence(file);if(prepared.blob.size>7_500_000)throw new Error("O arquivo excede 7,5 MB.");const base64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]||"");reader.onerror=()=>reject(new Error("Não foi possível ler o arquivo."));reader.readAsDataURL(prepared.blob)});const uploaded=await request<Evidence>(`/inspections/${id}/evidence`,{method:"POST",body:JSON.stringify({type,title:title||evidenceTypes.find(x=>x[0]===type)?.[1]||"Evidência",description,fileName:prepared.fileName,mimeType:prepared.mimeType,base64,capturedAt:new Date(file.lastModified).toISOString(),measurementKey})});upd("evidence",data.evidence.some(item=>item.id===uploaded.id)?data.evidence.map(item=>item.id===uploaded.id?uploaded:item):[...data.evidence,uploaded]);setSaved(true)}catch(x){setError(x instanceof Error?x.message:"Não foi possível anexar o arquivo")}finally{setBusy(false)}};
 const removeEvidence=async(evidence:Evidence)=>{if(!evidence.id){upd("evidence",data.evidence.filter(item=>item!==evidence));return}const id=draftId;if(!id)return;setBusy(true);setError("");try{await request(`/inspections/${id}/evidence/${evidence.id}`,{method:"DELETE"});upd("evidence",data.evidence.filter(item=>item.id!==evidence.id))}catch(x){setError(x instanceof Error?x.message:"Não foi possível remover a evidência")}finally{setBusy(false)}};
 const submit=(e:FormEvent)=>{e.preventDefault();void persist(true)};
 return <><div className="pageHead"><div><small>{draftId?"CONTINUANDO RASCUNHO":"NOVA INSPEÇÃO"}</small><h1>{draftId?"Continuar inspeção em rascunho":"Criar nova inspeção NR-13"}</h1><p>{draftId?"Revise os dados já salvos antes de concluir.":"Um novo atendimento será criado; nenhum rascunho existente será alterado."}</p></div><button type="button" className="secondaryBtn" disabled={busy||!selected} onClick={()=>void persist(false)}><Icon name="save"/>{busy?"Salvando…":draftId?"Atualizar rascunho":"Criar rascunho"}</button></div>
 {sourceReportId&&<div className="inspectionContext"><small>RASCUNHO REAPROVEITADO</small><b>Revise a competência, todas as datas e os dados técnicos</b><span>Assinaturas e evidências do atendimento anterior não foram copiadas. Uma nova numeração será criada somente após a conclusão e o envio para emissão.</span></div>}
 <div className="stepper inspectionStepper">{steps.map((label,index)=><button type="button" disabled={index>0&&!selected} className={index===step?"current":index<step?"done":""} key={label} onClick={()=>setStep(index)}><span>{index<step?<Icon name="check"/>:index+1}</span><small>{label}</small></button>)}</div>
 <form className="panel inspectForm technicalInspection" onSubmit={submit}>
  {step===6&&<div className="inspectionContext"><small>RESUMO DE FINALIZAÇÃO</small><b>{Object.values(data.documentation).filter(value=>value==="NOT_VERIFIED").length===0&&data.conclusion&&data.scope.finishedAt?"Pronta para concluir":"Há pendências para revisar"}</b><span>{Object.values(data.documentation).filter(value=>value==="NOT_VERIFIED").length} documento(s) não verificado(s) · {!data.scope.finishedAt?"fim da inspeção pendente · ":""}{!data.conclusion?"parecer conclusivo pendente · ":""}{company?.measurementPhotoRequired?`${data.readings.filter(r=>r.value!==""&&!data.evidence.some(e=>e.measurementKey===r.key)).length} foto(s) obrigatória(s) pendente(s)`:"fotos opcionais"}. Rascunhos podem ser retomados antes da conclusão.</span></div>}
  {step===4&&data.devices.length>0&&<section className="periodicityPanel"><h3>Unidades e validade dos dispositivos</h3>{data.devices.map((device,index)=><div className="inspectionGrid" key={`${device.kind}-${index}`}><Field label={`${device.tag||`Dispositivo ${index+1}`} · unidade de pressão`}><select value={device.pressureUnit||"bar"} onChange={e=>upd("devices",data.devices.map((item,n)=>n===index?{...item,pressureUnit:e.target.value as Device["pressureUnit"]}:item))}><option value="bar">bar</option><option value="kPa">kPa</option><option value="MPa">MPa</option><option value="psi">psi</option></select></Field><Field label="Periodicidade da calibração"><select value={device.periodicityYears||""} onChange={e=>{const years=Number(e.target.value);upd("devices",data.devices.map((item,n)=>n===index?{...item,periodicityYears:years||undefined,dueDate:years&&item.calibrationDate?addCalendarYears(item.calibrationDate,years):item.dueDate}:item))}}><option value="">Selecione</option><option value="1">Anual</option><option value="2">Bienal</option><option value="3">Trienal</option><option value="4">Quadrienal</option><option value="5">Quinquenal</option></select></Field><Field label="Validade calculada / revisável"><input type="date" value={device.dueDate} onChange={e=>upd("devices",data.devices.map((item,n)=>n===index?{...item,dueDate:e.target.value}:item))}/></Field></div>)}</section>}
  {step===5&&<section className="periodicityPanel"><h3>Aplicabilidade de recomendações e teste hidrostático</h3><div className="inspectionGrid"><Field label="Recomendações se aplicam?"><select value={data.recommendationPlan?.applicable===false?"NO":"YES"} onChange={e=>upd("recommendationPlan",{applicable:e.target.value==="YES",dueDate:data.recommendationPlan?.dueDate||data.deadlines.recommendationDue})}><option value="YES">Aplica</option><option value="NO">Não se aplica</option></select></Field>{data.recommendationPlan?.applicable!==false&&<Field label="Data das recomendações"><input type="date" value={data.recommendationPlan?.dueDate||data.deadlines.recommendationDue} onChange={e=>{upd("recommendationPlan",{applicable:true,dueDate:e.target.value});upd("deadlines",{...data.deadlines,recommendationDue:e.target.value})}}/></Field>}<Field label="Teste hidrostático se aplica?"><select value={data.hydrostaticPlan?.applicable===false?"NO":"YES"} onChange={e=>upd("hydrostaticPlan",{applicable:e.target.value==="YES",periodicityYears:data.hydrostaticPlan?.periodicityYears,nextDate:data.hydrostaticPlan?.nextDate||data.deadlines.nextHydrostatic})}><option value="YES">Aplica</option><option value="NO">Não se aplica</option></select></Field>{data.hydrostaticPlan?.applicable!==false&&<Field label="Próxima data do teste"><input type="date" value={data.hydrostaticPlan?.nextDate||data.deadlines.nextHydrostatic} onChange={e=>{upd("hydrostaticPlan",{applicable:true,periodicityYears:data.deadlines.hydrostaticPeriodYears,nextDate:e.target.value});upd("deadlines",{...data.deadlines,nextHydrostatic:e.target.value})}}/></Field>}</div></section>}
  {step===2&&<div className="inspectionContext"><small>PROGRESSO DOS DOCUMENTOS DE SEGURANÇA</small><b>{Object.values(data.documentation).filter(value=>value!=="NOT_VERIFIED").length} de {Object.keys(data.documentation).length} itens preenchidos</b><span>{Math.round(Object.values(data.documentation).filter(value=>value!=="NOT_VERIFIED").length*100/Object.keys(data.documentation).length)}% concluído · salvo junto ao rascunho para retomada.</span></div>}
  {step===1&&<VolumePanel value={data} onChange={setData} onError={setError}/>}
  {step===0&&<section className="periodicityPanel"><h3>Dados preliminares do laudo</h3><p className="technicalNote">Informações administrativas e de localização. Campos vazios não aparecem no PDF.</p><div className="inspectionGrid">{([['ownerName','Proprietário'],['ownerCnpj','CNPJ'],['ownerAddress','Endereço'],['site','Local / unidade'],['factory','Fábrica'],['sector','Setor'],['coordinates','Coordenadas'],['inspectionCompany','Empresa inspetora'],['professionalQualification','Qualificação profissional'],['professionalRegistry','CREA / registro'],['artNumber','ART / TRT']] as const).map(([key,label])=><Field label={label} key={key}><input value={data.preliminary?.[key]||""} onChange={e=>upd("preliminary",{...emptyInspectionData().preliminary!,...data.preliminary,[key]:e.target.value})}/></Field>)}</div></section>}
  {step===4&&<section className="periodicityPanel"><div className="formTitle"><Icon name="check"/><div><h2>Itens de segurança calibrados (válvulas e manômetros)?</h2><p>Registre a situação verificada no início da inspeção.</p></div></div><div className="inspectionGrid"><Field label="Situação"><select value={data.safetyCalibration?.calibrated||""} onChange={e=>upd("safetyCalibration",{calibrated:e.target.value as ""|"YES"|"NO",dueDate:data.safetyCalibration?.dueDate||"",evidenceIds:data.safetyCalibration?.evidenceIds||[]})}><option value="">Selecione</option><option value="YES">Sim</option><option value="NO">Não</option></select></Field>{data.safetyCalibration?.calibrated==="YES"&&<Field label="Data de vencimento"><input required type="date" value={data.safetyCalibration.dueDate} onChange={e=>upd("safetyCalibration",{...data.safetyCalibration!,dueDate:e.target.value})}/></Field>}</div>{data.safetyCalibration?.calibrated==="YES"&&<><p className="technicalNote">Anexe abaixo foto(s) dos itens ou certificados. As evidências ficam persistidas no armazenamento padrão da inspeção.</p><EvidenceUploader busy={busy} onUpload={(file,type,title,description)=>void uploadEvidence(file,type,title||"Item de segurança calibrado",description)}/></>}</section>}
  {step===5&&<section className="periodicityPanel"><div className="formTitle"><Icon name="calendar"/><div><h2>Periodicidade e próximas datas</h2><p>O exame externo é o padrão. Inclua o interno somente quando ele fizer parte deste atendimento.</p></div></div><label className="policyCheck"><input type="checkbox" checked={has("INTERNAL")} onChange={()=>{toggleExam("INTERNAL");if(has("INTERNAL"))upd("deadlines",{...data.deadlines,internalPeriodYears:undefined,nextInternal:""})}}/>Realizar também a periodicidade interna</label><div className="inspectionGrid">{([['externalPeriodYears','nextExternal','Exame externo'],...(has("INTERNAL")?([['internalPeriodYears','nextInternal','Exame interno']] as const):[]),['hydrostaticPeriodYears','nextHydrostatic','Teste hidrostático']] as const).map(([periodKey,dateKey,label])=><div className="deadlinePair" key={periodKey}><Field label={`Periodicidade — ${label}`}><select value={data.deadlines[periodKey]||""} onChange={e=>setDeadlinePeriod(periodKey,dateKey,Number(e.target.value))}><option value="">Selecione</option><option value="1">Anual</option><option value="2">Bienal</option><option value="3">Trienal</option><option value="4">Quadrienal</option><option value="5">Quinquenal</option></select></Field><Field label={`Próxima data — ${label}`}><input type="date" value={data.deadlines[dateKey]} onChange={e=>upd("deadlines",{...data.deadlines,[dateKey]:e.target.value})}/><small>Calculada automaticamente; revisão manual permitida.</small></Field></div>)}</div></section>}
  {step===0&&<section><div className="formTitle"><Icon name="equipment"/><div><h2>Escopo e identificação da inspeção</h2><p>Tipo do equipamento e exames efetivamente realizados controlam as demais seções.</p></div></div><div className="inspectionContext"><small>EMPRESA DA INSPEÇÃO</small><b>{company?.name||filteredCompany?.name||"Selecione uma empresa no filtro superior"}</b><span>{company||filteredCompany?(company||filteredCompany)?.measurementPhotoRequired?"Política: foto obrigatória em cada ponto de medição.":"Política: foto opcional nos pontos de medição.":"Escolha uma empresa e, abaixo, um equipamento vinculado a ela."}</span></div><div className="equipmentChoice">{available.map(item=>{const owner=companies.find(c=>c.id===item.companyId);return <label className={selected===item.id?"chosen":""} key={item.id}><input type="radio" checked={selected===item.id} onChange={()=>chooseEquipment(item.id)}/><Icon name="equipment"/><span><b>{item.tag} · {item.name}</b><small>{owner?.name}</small><em className={owner?.measurementPhotoRequired?"photoPolicy required":"photoPolicy"}>{owner?.measurementPhotoRequired?"Foto obrigatória por ponto":"Foto opcional por ponto"}</em></span><Icon name="check"/></label>})}</div>{available.length===0&&<div className="inspectionEmpty"><b>Nenhum equipamento disponível para esta empresa.</b><span>{filteredCompany?.measurementPhotoRequired?"A política de foto obrigatória está ativa, mas será aplicada somente após vincular um equipamento a esta empresa.":"Cadastre ou vincule um equipamento antes de iniciar a inspeção."}</span><Link className="secondaryBtn" href="/app/equipamentos">Ir para cadastro de equipamentos</Link></div>}<div className="inspectionGrid"><Field label="Tipo de equipamento"><select value={data.scope.equipmentKind} onChange={e=>upd("scope",{...data.scope,equipmentKind:e.target.value as InspectionTechnicalData["scope"]["equipmentKind"]})}><option value="PRESSURE_VESSEL">Vaso de pressão</option><option value="HEAT_EXCHANGER">Trocador de calor</option></select></Field><Field label="Tipo de inspeção"><select value={data.scope.inspectionType} onChange={e=>upd("scope",{...data.scope,inspectionType:e.target.value})}><option value="INITIAL">Inicial</option><option value="PERIODIC_EXTERNAL">Periódica externa</option><option value="PERIODIC_INTERNAL">Periódica interna</option><option value="EXTRAORDINARY">Extraordinária</option></select></Field><Field label="Início">{text(data.scope.startedAt,v=>upd("scope",{...data.scope,startedAt:v}),true)}</Field><Field label="ART vinculada">{text(data.scope.artNumber,v=>upd("scope",{...data.scope,artNumber:v}))}</Field></div><div className="examChoices">{[["EXTERNAL","Exame externo"],["INTERNAL","Exame interno"],["ULTRASOUND","Ultrassom / espessura"],["HYDROSTATIC","Teste hidrostático"],["ACCUMULATION","Ensaio de acumulação"],["PRESSURE_CALIBRATION","Calibração de pressão"]].map(([v,l])=><label key={v}><input type="checkbox" checked={has(v)} onChange={()=>toggleExam(v)}/>{l}</label>)}</div>{company?.measurementPhotoRequired&&!has("ULTRASOUND")&&<p className="technicalNote">A empresa exige foto em todos os pontos. Selecione “Ultrassom / espessura” para cadastrar os pontos e anexar suas evidências.</p>}</section>}
  {step===1&&<section><div className="formTitle"><Icon name="equipment"/><div><h2>Dados técnicos do equipamento</h2><p>{company?.name} · {asset?.tag}</p></div></div><datalist id="codes"><option value="ASME VIII Div. 1"/><option value="ASME VIII Div. 2"/><option value="EN 13445"/></datalist><div className="inspectionGrid"><Field label="Local / setor">{text(data.identification.location,v=>setId("location",v))}</Field><div className="inspectionField"><span>Fabricante</span><ManufacturerCatalogField value={data.identification.manufacturer} onChange={value=>setId("manufacturer",value)}/></div><Field label="Modelo / tipo">{text(data.identification.model,v=>setId("model",v))}</Field><Field label="Número de série">{text(data.identification.serialNumber,v=>setId("serialNumber",v))}</Field><Field label="Ano de fabricação"><input type="number" min="1800" max={new Date().getFullYear()+1} step="1" value={data.identification.manufactureYear} onChange={e=>setId("manufactureYear",e.target.value)}/></Field><Field label="Código de construção / edição"><input list="codes" value={data.identification.constructionCode} onChange={e=>setId("constructionCode",e.target.value)} placeholder="Selecione ou informe outro"/></Field><Field label="Volume / capacidade (L)"><input type="number" min="0" step="0.01" value={data.identification.volume} onChange={e=>setId("volume",e.target.value)}/></Field><Field label="Fluido de trabalho">{text(data.identification.fluid,v=>setId("fluid",v))}</Field><Field label="Classe do fluido"><select value={data.identification.fluidClass} onChange={e=>setId("fluidClass",e.target.value)}><option value="">Selecione</option>{["A","B","C","D"].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Categoria NR-13"><select value={data.identification.vesselCategory} onChange={e=>setId("vesselCategory",e.target.value)}><option value="">Selecione</option>{["I","II","III","IV","V"].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Grupo potencial de risco"><select value={data.identification.riskGroup} onChange={e=>setId("riskGroup",e.target.value)}><option value="">Selecione</option>{["1","2","3","4","5"].map(v=><option key={v}>{v}</option>)}</select></Field><Field label={`Pressão de projeto / ${data.identification.pressureUnit||"bar"}`}><div className="pressureField"><input aria-label="Valor da pressão de projeto" type="number" min="0" step="0.01" inputMode="decimal" value={data.identification.designPressure} onChange={e=>setId("designPressure",e.target.value)}/><select aria-label="Unidade da pressão de projeto" value={data.identification.pressureUnit||"bar"} onChange={e=>setId("pressureUnit",e.target.value)}>{pressureUnits.map(unit=><option value={unit} key={unit}>{unit}</option>)}</select></div></Field>{([['operatingPressure',`Pressão de operação (${data.identification.pressureUnit||"bar"})`],['pmta',`PMTA (${data.identification.pressureUnit||"bar"})`],['designTemperature','Temperatura de projeto (°C)'],['hydrostaticTestPressure',`Pressão de prova (${data.identification.pressureUnit||"bar"})`]] as [keyof InspectionTechnicalData['identification'],string][]).map(([k,l])=><Field label={l} key={k}><input type="number" min="0" step="0.01" inputMode="decimal" value={String(data.identification[k])} onChange={e=>setId(k,e.target.value)}/></Field>)}<Field label="Material">{text(data.identification.material,v=>setId("material",v))}</Field><Field label="Orientação / formato"><select value={data.identification.orientation} onChange={e=>setId("orientation",e.target.value)}><option value="">Selecione</option><option>Cilíndrico horizontal</option><option>Cilíndrico vertical</option><option>Esférico</option><option>Outro</option></select></Field></div>{data.scope.equipmentKind==="HEAT_EXCHANGER"&&<Field label="Circuito interno / feixe (fluido, volume, pressões e categoria)" wide><textarea value={data.identification.internalCircuitDescription} onChange={e=>setId("internalCircuitDescription",e.target.value)}/></Field>}</section>}
  {step===1&&<PmtaCalculationPanel value={data.pmtaCalculation||{mode:"NOT_CALCULATED",reason:""}} onChange={value=>setData(current=>({...current,schemaVersion:4,pmtaCalculation:value,identification:{...current.identification,pmta:value.mode==="CALCULATED"&&value.adoptedResultBar!==undefined?String(value.adoptedResultBar):""}}))}/>}
  {step===1&&data.scope.equipmentKind==="HEAT_EXCHANGER"&&<section className="periodicityPanel"><div className="subhead"><h3>Circuitos independentes — casco e feixe</h3><button type="button" className="secondaryBtn" onClick={()=>upd("equipmentCircuits",[...(data.equipmentCircuits||[]),{key:crypto.randomUUID(),name:"",fluid:"",fluidClass:"",volume:"",operatingPressure:"",designPressure:"",pmta:"",hydrostaticTestPressure:"",vesselCategory:"",readings:[]}])}>Adicionar circuito</button></div>{(data.equipmentCircuits||[]).map((circuit,index)=><div className="arrayRow" key={circuit.key}>{([['name','Circuito'],['fluid','Fluido'],['fluidClass','Classe'],['volume','Volume'],['operatingPressure','Pressão operação'],['designPressure','Pressão projeto'],['pmta','PMTA'],['hydrostaticTestPressure','TH'],['vesselCategory','Categoria']] as const).map(([key,label])=><Field label={label} key={key}><input value={circuit[key]} onChange={e=>upd("equipmentCircuits",data.equipmentCircuits!.map((item,n)=>n===index?{...item,[key]:e.target.value}:item))}/></Field>)}<button type="button" className="removeBtn" onClick={()=>upd("equipmentCircuits",data.equipmentCircuits!.filter((_,n)=>n!==index))}>Remover</button></div>)}</section>}
  {step===2&&<section><div className="formTitle"><Icon name="clipboard"/><div><h2>Documentação e segurança</h2><p>Use “Não verificado” quando não houver evidência; não presuma conformidade.</p></div></div><div className="technicalChecklist">{Object.entries(docLabels).map(([key,label])=><div key={key}><span>{label}</span><select value={data.documentation[key]} onChange={e=>upd("documentation",{...data.documentation,[key]:e.target.value as Answer})}>{answers.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></div>)}</div></section>}
  {step===2&&<section className="periodicityPanel"><div className="subhead"><h3>Checklist configurável de inspeção</h3><button type="button" className="secondaryBtn" onClick={()=>upd("checklistItems",[...(data.checklistItems||[]),{key:crypto.randomUUID(),group:"Personalizado",label:"",answer:"NOT_VERIFIED",observation:"",enabled:true}])}>Adicionar item</button></div>{(data.checklistItems||[]).map((item,index)=><div className="arrayRow" key={item.key}><Field label="Usar"><input type="checkbox" checked={item.enabled} onChange={e=>upd("checklistItems",data.checklistItems!.map((value,n)=>n===index?{...value,enabled:e.target.checked}:value))}/></Field><Field label="Grupo"><input value={item.group} onChange={e=>upd("checklistItems",data.checklistItems!.map((value,n)=>n===index?{...value,group:e.target.value}:value))}/></Field><Field label="Item"><input value={item.label} onChange={e=>upd("checklistItems",data.checklistItems!.map((value,n)=>n===index?{...value,label:e.target.value}:value))}/></Field><Field label="Resposta"><select value={item.answer} onChange={e=>upd("checklistItems",data.checklistItems!.map((value,n)=>n===index?{...value,answer:e.target.value as Answer}:value))}>{answers.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Observação"><input value={item.observation} onChange={e=>upd("checklistItems",data.checklistItems!.map((value,n)=>n===index?{...value,observation:e.target.value}:value))}/></Field><button type="button" className="removeBtn" onClick={()=>upd("checklistItems",data.checklistItems!.filter((_,n)=>n!==index))}>Remover</button></div>)}</section>}
  {step===3&&<section><div className="formTitle"><Icon name="clipboard"/><div><h2>Exames, ensaios e medições</h2><p>Registre resultados e fundamento técnico quando um ensaio não for realizado.</p></div></div>{has("EXTERNAL")&&<><h3>Exame externo</h3><div className="inspectionGrid"><Field label="Resultado"><select value={data.examinations.externalResult} onChange={e=>upd("examinations",{...data.examinations,externalResult:e.target.value as Answer})}>{answers.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Observações" wide><textarea value={data.examinations.externalNotes} onChange={e=>upd("examinations",{...data.examinations,externalNotes:e.target.value})}/></Field></div></>}{has("INTERNAL")&&<><h3>Exame interno</h3><div className="inspectionGrid"><Field label="Resultado"><select value={data.examinations.internalResult} onChange={e=>upd("examinations",{...data.examinations,internalResult:e.target.value as Answer})}>{answers.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Observações" wide><textarea value={data.examinations.internalNotes} onChange={e=>upd("examinations",{...data.examinations,internalNotes:e.target.value})}/></Field></div></>}{has("HYDROSTATIC")&&<div className="inspectionGrid"><Field label="Pressão do teste">{text(data.examinations.hydrostaticPressure,v=>upd("examinations",{...data.examinations,hydrostaticPressure:v}))}</Field><Field label="Tempo mantido">{text(data.examinations.hydrostaticDuration,v=>upd("examinations",{...data.examinations,hydrostaticDuration:v}))}</Field><Field label="Resultado/fundamento da não realização" wide><textarea value={data.examinations.hydrostaticResult||data.examinations.hydrostaticWaiverBasis} onChange={e=>upd("examinations",{...data.examinations,hydrostaticResult:e.target.value})}/></Field></div>}{!has("ULTRASOUND")&&<p className="technicalNote">Para cadastrar pontos de medição e anexar fotos, selecione “Ultrassom / espessura” na etapa Escopo.</p>}{has("ULTRASOUND")&&<>{company?.measurementPhotoRequired&&<p className="technicalNote">Esta empresa exige ao menos uma foto em cada ponto preenchido. Pontos pendentes são identificados abaixo.</p>}<div className="subhead"><h3>Medições de espessura</h3><button type="button" className="secondaryBtn" onClick={()=>upd("readings",[...data.readings,{key:crypto.randomUUID(),point:"",component:"",value:"",unit:"mm"}])}>Adicionar ponto</button></div>{data.readings.map((r,i)=>{const pointEvidence=data.evidence.filter(ev=>ev.measurementKey===r.key);const photoPending=company?.measurementPhotoRequired&&r.value!==""&&pointEvidence.length===0;return <div className={photoPending?"arrayRow measurementPending":"arrayRow"} key={r.key||i}>{([['point','Ponto'],['component','Componente'],['value','Valor'],['unit','Unidade'],['minimum','Mínimo/ref.'],['observation','Observação']] as [keyof Reading,string][]).map(([k,l])=><Field label={l} key={k}>{text(r[k]||"",v=>upd("readings",data.readings.map((x,n)=>n===i?{...x,[k]:v}:x)))}</Field>)}<div className="measurementPhotos"><div className="measurementPhotoStatus"><b>Fotos do ponto · {company?.measurementPhotoRequired?"obrigatória":"opcional"}</b><span className={photoPending?"pending":"complete"}>{pointEvidence.length?`${pointEvidence.length} foto${pointEvidence.length>1?"s":""} anexada${pointEvidence.length>1?"s":""}`:photoPending?"Foto pendente":"Nenhuma foto anexada"}</span></div><label className="uploadButton">{busy?"Enviando…":"Adicionar foto"}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onChange={e=>{const file=e.target.files?.[0];if(file){void uploadEvidence(file,"COMPONENT",`Ponto ${r.point||i+1}`,r.component||"Foto do ponto de medição",r.key);e.target.value=""}}}/></label>{pointEvidence.map((ev,n)=><span className="measurementPhoto" key={ev.id||n}>{(ev.dataUrl||ev.url)&&<img src={ev.dataUrl||ev.url} alt={ev.title}/>}<button type="button" aria-label={`Remover foto do ponto ${r.point||i+1}`} onClick={()=>void removeEvidence(ev)}>×</button></span>)}</div><button type="button" className="removeBtn" onClick={()=>upd("readings",data.readings.filter((_,n)=>n!==i))}>Remover</button></div>})}</>}</section>}
  {step===3&&<section className="periodicityPanel"><h3>Parecer das medições</h3><Field label="Conclusão da medição de espessura" wide><textarea value={data.thicknessOpinion||""} onChange={e=>upd("thicknessOpinion",e.target.value)}/></Field><div className="subhead"><h3>Componentes observados</h3><button type="button" className="secondaryBtn" onClick={()=>upd("observedComponents",[...(data.observedComponents||[]),{key:crypto.randomUUID(),component:"",condition:"NOT_VERIFIED",observation:""}])}>Adicionar componente</button></div>{(data.observedComponents||[]).map((item,index)=><div className="arrayRow" key={item.key}><Field label="Componente"><input value={item.component} onChange={e=>upd("observedComponents",data.observedComponents!.map((value,n)=>n===index?{...value,component:e.target.value}:value))}/></Field><Field label="Condição"><select value={item.condition} onChange={e=>upd("observedComponents",data.observedComponents!.map((value,n)=>n===index?{...value,condition:e.target.value as Answer}:value))}>{answers.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Observação"><input value={item.observation} onChange={e=>upd("observedComponents",data.observedComponents!.map((value,n)=>n===index?{...value,observation:e.target.value}:value))}/></Field><button type="button" className="removeBtn" onClick={()=>upd("observedComponents",data.observedComponents!.filter((_,n)=>n!==index))}>Remover</button></div>)}</section>}
  {step===3&&has("ULTRASOUND")&&<section className="periodicityPanel"><h3>Método e rastreabilidade do ultrassom</h3><div className="inspectionGrid">{([['instrument','Instrumento'],['manufacturer','Fabricante'],['model','Modelo'],['serialNumber','Série'],['procedure','Procedimento'],['probe','Cabeçote'],['referenceBlock','Bloco/padrão'],['calibrationCertificate','Certificado'],['calibrationDate','Data calibração'],['calibrationDueDate','Validade'],['sketchReference','Croqui'],['corrosionRate','Taxa de corrosão'],['remainingLife','Vida remanescente']] as const).map(([key,label])=><Field label={label} key={key}><input type={key.includes("Date")?"date":"text"} value={data.utMethod?.[key]||""} onChange={e=>upd("utMethod",{...emptyInspectionData().utMethod!,...data.utMethod,[key]:e.target.value})}/></Field>)}<Field label="Memória de cálculo" wide><textarea value={data.utMethod?.calculationMemory||""} onChange={e=>upd("utMethod",{...emptyInspectionData().utMethod!,...data.utMethod,calculationMemory:e.target.value})}/></Field></div><div className="subhead"><h3>Outros END / ensaios</h3><button type="button" className="secondaryBtn" onClick={()=>upd("ndtTests",[...(data.ndtTests||[]),{key:crypto.randomUUID(),method:"PT",area:"",procedure:"",date:"",result:"NOT_VERIFIED",reportReference:"",observation:""}])}>Adicionar ensaio</button></div>{(data.ndtTests||[]).map((item,index)=><div className="arrayRow" key={item.key}><Field label="Método"><select value={item.method} onChange={e=>upd("ndtTests",data.ndtTests!.map((value,n)=>n===index?{...value,method:e.target.value as typeof item.method}:value))}><option value="PT">Líquido penetrante</option><option value="MT">Partículas magnéticas</option><option value="LEAK">Estanqueidade</option><option value="RADIOGRAPHY">Radiografia</option><option value="OTHER">Outro</option></select></Field>{([['area','Área'],['procedure','Procedimento'],['date','Data'],['reportReference','Relatório'],['observation','Observação']] as const).map(([key,label])=><Field label={label} key={key}><input type={key==="date"?"date":"text"} value={item[key]} onChange={e=>upd("ndtTests",data.ndtTests!.map((value,n)=>n===index?{...value,[key]:e.target.value}:value))}/></Field>)}<Field label="Resultado"><select value={item.result} onChange={e=>upd("ndtTests",data.ndtTests!.map((value,n)=>n===index?{...value,result:e.target.value as Answer}:value))}>{answers.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><button type="button" className="removeBtn" onClick={()=>upd("ndtTests",data.ndtTests!.filter((_,n)=>n!==index))}>Remover</button></div>)}</section>}
  {step===4&&<section><div className="formTitle"><Icon name="equipment"/><div><h2>Dispositivos de segurança e medição</h2><p>PSVs e medidores mantêm referência aos seus certificados.</p></div></div><div className="subhead"><h3>Dispositivos</h3><button type="button" className="secondaryBtn" onClick={()=>upd("devices",[...data.devices,{kind:"PSV",tag:"",manufacturer:"",serialNumber:"",range:"",setPressure:"",certificateNumber:"",calibrationDate:"",dueDate:"",result:""}])}>Adicionar dispositivo</button></div>{data.devices.map((d,i)=><div className="arrayRow deviceRow" key={i}><Field label="Tipo de dispositivo"><div className="deviceTypeField"><select value={d.kind} onChange={e=>selectDeviceType(i,e.target.value)}><option value="PSV">PSV / válvula de segurança</option><option value="PRESSURE_GAUGE">Manômetro / medidor de pressão</option>{deviceTypes.map(item=><option value={item.name} key={item.id}>{item.name}</option>)}</select><button type="button" className="secondaryBtn" onClick={()=>openDeviceType(i)}>Adicionar tipo</button></div></Field>{([['tag','TAG'],['manufacturer','Fabricante'],['serialNumber','Nº série'],['range','Faixa/escala'],['setPressure','Pressão abertura'],['certificateNumber','Certificado'],['calibrationDate','Data calibração'],['dueDate','Validade'],['result','Resultado']] as [keyof Device,string][]).map(([k,l])=><Field label={l} key={k}>{text(String(d[k]),v=>upd("devices",data.devices.map((x,n)=>n===i?{...x,[k]:v}:x)))}</Field>)}<button type="button" className="removeBtn" onClick={()=>upd("devices",data.devices.filter((_,n)=>n!==i))}>Remover</button></div>)}{has("PRESSURE_CALIBRATION")&&<><h3>Dados do certificado de calibração</h3><p className="technicalNote">Campos baseados no DOQ-CGCRE-047 como orientação técnica, não como requisito normativo obrigatório.</p><div className="inspectionGrid">{([['method','Método'],['procedure','Procedimento'],['ambientTemperature','Temperatura ambiente'],['atmosphericPressure','Pressão atmosférica'],['cycles','Ciclos'],['standardType','Tipo de padrão'],['standardId','Identificação do padrão'],['standardCertificate','Certificado do padrão'],['standardUncertainty','Incerteza do padrão'],['conversionFactor','Fator de conversão'],['result','Resultado']] as [keyof InspectionTechnicalData['calibration'],string][]).map(([k,l])=><Field label={l} key={k}>{text(String(data.calibration[k]),v=>upd("calibration",{...data.calibration,[k]:v}))}</Field>)}</div></>}</section>}
  {step===5&&<section><div className="formTitle"><Icon name="file"/><div><h2>Recomendações, conclusão e prazos</h2><p>Preencha os campos obrigatórios desta seção antes de continuar. O conteúdo será reproduzido no laudo sem redigitação.</p></div></div><div className="inspectionGrid"><Field label="Resultado"><select value={data.result} onChange={e=>upd("result",e.target.value as InspectionTechnicalData["result"])}><option value="APPROVED">Aprovado</option><option value="APPROVED_WITH_RECOMMENDATIONS">Aprovado com recomendações</option><option value="REJECTED">Reprovado</option></select></Field><Field label="Fim da inspeção (obrigatório)"><input id="inspection-finished-at" aria-invalid={error==="Informe a data de conclusão."} aria-describedby={error==="Informe a data de conclusão."?"inspection-validation-error":undefined} type="date" required value={data.scope.finishedAt} onChange={e=>upd("scope",{...data.scope,finishedAt:e.target.value})}/></Field><Field label="Recomendações / providências" wide><textarea value={data.recommendations} onChange={e=>upd("recommendations",e.target.value)}/></Field><Field label="Parecer conclusivo (obrigatório)" wide><textarea id="inspection-conclusion" aria-invalid={error==="Informe o parecer conclusivo."} aria-describedby={error==="Informe o parecer conclusivo."?"inspection-validation-error":undefined} required value={data.conclusion} onChange={e=>upd("conclusion",e.target.value)}/></Field>{([['nextExternal','Próximo exame externo'],['nextInternal','Próximo exame interno'],['nextHydrostatic','Próximo teste hidrostático'],['recommendationDue','Prazo das recomendações']] as [keyof InspectionTechnicalData['deadlines'],string][]).map(([k,l])=><Field label={l} key={k}><input id={k==="nextExternal"?"inspection-next-external":undefined} type="date" value={data.deadlines[k]} onChange={e=>upd("deadlines",{...data.deadlines,[k]:e.target.value})}/></Field>)}</div><div className="subhead"><h3>Fotos e evidências</h3><span>JPEG, PNG ou WebP · compactação automática · até 7,5 MB</span></div><EvidenceUploader busy={busy} onUpload={(file,type,title,description)=>void uploadEvidence(file,type,title,description)}/><div className="evidenceGallery">{data.evidence.map((ev,i)=><article key={ev.id||i}>{(ev.dataUrl||ev.url)&&<img src={ev.dataUrl||ev.url} alt={ev.title}/>}<div><small>{evidenceTypes.find(x=>x[0]===ev.type)?.[1]||"Evidência"}</small><b>{ev.title||"Sem legenda"}</b><span>{ev.description}</span>{ev.sha256&&<code title={ev.sha256}>SHA-256 {ev.sha256.slice(0,12)}…</code>}</div><button type="button" disabled={busy} className="removeBtn" onClick={()=>void removeEvidence(ev)}>Remover</button></article>)}</div></section>}
  {step===5&&<section className="periodicityPanel"><div className="subhead"><h3>Não conformidades e plano de ação</h3><button type="button" className="secondaryBtn" onClick={()=>upd("nonConformities",[...(data.nonConformities||[]),{key:crypto.randomUUID(),description:"",criticality:"MEDIUM",correctiveAction:"",dueDate:"",responsible:"",evidenceReference:"",status:"OPEN"}])}>Adicionar não conformidade</button></div>{(data.nonConformities||[]).map((item,index)=><div className="arrayRow" key={item.key}>{([['description','Descrição'],['correctiveAction','Ação corretiva'],['responsible','Responsável'],['evidenceReference','Evidência']] as const).map(([key,label])=><Field label={label} key={key}><input value={item[key]} onChange={e=>upd("nonConformities",data.nonConformities!.map((value,n)=>n===index?{...value,[key]:e.target.value}:value))}/></Field>)}<Field label="Criticidade"><select value={item.criticality} onChange={e=>upd("nonConformities",data.nonConformities!.map((value,n)=>n===index?{...value,criticality:e.target.value as typeof item.criticality}:value))}><option value="LOW">Baixa</option><option value="MEDIUM">Média</option><option value="HIGH">Alta</option><option value="CRITICAL">Crítica</option></select></Field><Field label="Prazo"><input type="date" value={item.dueDate} onChange={e=>upd("nonConformities",data.nonConformities!.map((value,n)=>n===index?{...value,dueDate:e.target.value}:value))}/></Field><Field label="Status"><select value={item.status} onChange={e=>upd("nonConformities",data.nonConformities!.map((value,n)=>n===index?{...value,status:e.target.value as typeof item.status}:value))}><option value="OPEN">Aberta</option><option value="IN_PROGRESS">Em andamento</option><option value="MONITORING">Em monitoramento</option><option value="RESOLVED">Resolvida</option></select></Field><button type="button" className="removeBtn" onClick={()=>upd("nonConformities",data.nonConformities!.filter((_,n)=>n!==index))}>Remover</button></div>)}<h3>Conclusão técnica detalhada</h3><div className="inspectionGrid"><Field label="Condição da PMTA"><select value={data.conclusionDetails?.pmtaDisposition||"NOT_EVALUATED"} onChange={e=>upd("conclusionDetails",{...emptyInspectionData().conclusionDetails!,...data.conclusionDetails,pmtaDisposition:e.target.value as "MAINTAINED"|"REVISED"|"NOT_EVALUATED"})}><option value="NOT_EVALUATED">Não avaliada</option><option value="MAINTAINED">Mantida</option><option value="REVISED">Revisada</option></select></Field>{data.conclusionDetails?.pmtaDisposition==="REVISED"&&<Field label="PMTA revisada"><input value={data.conclusionDetails.revisedPmta} onChange={e=>upd("conclusionDetails",{...data.conclusionDetails!,revisedPmta:e.target.value})}/></Field>}<Field label="Condições para operação" wide><textarea value={data.conclusionDetails?.operatingConditions||""} onChange={e=>upd("conclusionDetails",{...emptyInspectionData().conclusionDetails!,...data.conclusionDetails,operatingConditions:e.target.value})}/></Field><Field label="Restrições" wide><textarea value={data.conclusionDetails?.restrictions||""} onChange={e=>upd("conclusionDetails",{...emptyInspectionData().conclusionDetails!,...data.conclusionDetails,restrictions:e.target.value})}/></Field><Field label="Fundamentação normativa" wide><textarea value={data.conclusionDetails?.normativeBasis||""} onChange={e=>upd("conclusionDetails",{...emptyInspectionData().conclusionDetails!,...data.conclusionDetails,normativeBasis:e.target.value})}/></Field></div>{data.scope.inspectionType==="EXTRAORDINARY"&&<><h3>Gatilhos da inspeção extraordinária</h3><div className="examChoices">{["Dano ou acidente com potencial de comprometer a segurança","Alteração ou reparo importante","Retorno após inatividade prolongada","Mudança do local de instalação","Outro gatilho tecnicamente justificado"].map(trigger=><label key={trigger}><input type="checkbox" checked={(data.extraordinaryTriggers||[]).includes(trigger)} onChange={e=>upd("extraordinaryTriggers",e.target.checked?[...(data.extraordinaryTriggers||[]),trigger]:(data.extraordinaryTriggers||[]).filter(value=>value!==trigger))}/>{trigger}</label>)}</div></>}</section>}
  {step===5&&<section className="periodicityPanel"><h3>Controle do laudo e intervalo</h3><div className="inspectionGrid"><Field label="Revisão"><input value={data.revision||"00"} onChange={e=>upd("revision",e.target.value)}/></Field><Field label="Pressão autorizada"><input value={data.authorizedPressure||""} onChange={e=>upd("authorizedPressure",e.target.value)}/></Field><Field label="Justificativa do intervalo" wide><textarea value={data.inspectionIntervalBasis||""} onChange={e=>upd("inspectionIntervalBasis",e.target.value)}/></Field></div>{validateInspectionConsistency(data).length>0&&<div className="inspectionContext"><small>VALIDAÇÕES DE CONSISTÊNCIA</small><b>{validateInspectionConsistency(data).length} pendência(s)</b><span>{validateInspectionConsistency(data).map(item=>item.message).join(" · ")}</span></div>}</section>}
  {step===6&&<section><div className="formTitle"><Icon name="check"/><div><h2>Responsabilidade técnica</h2><p>Ao concluir, os dados são bloqueados após a emissão do laudo e preservados em versão.</p></div></div><div className="reviewSummary"><p><small>Empresa</small><b>{company?.name||"—"}</b></p><p><small>Equipamento</small><b>{asset?.tag} · {asset?.name}</b></p><p><small>Escopo</small><b>{data.scope.examinations.join(", ")}</b></p><p><small>Resultado</small><b>{data.result}</b></p></div><div className="signatureBox"><div><h3>Assinatura do responsável técnico</h3><p>Assine abaixo para concluir a inspeção.</p></div><canvas ref={canvasRef} width={640} height={180} onPointerDown={e=>{drawing.current=true;const r=e.currentTarget.getBoundingClientRect();const c=e.currentTarget.getContext("2d");c?.beginPath();c?.moveTo((e.clientX-r.left)*e.currentTarget.width/r.width,(e.clientY-r.top)*e.currentTarget.height/r.height)}} onPointerMove={e=>{if(!drawing.current)return;const r=e.currentTarget.getBoundingClientRect(),c=e.currentTarget.getContext("2d");c?.lineTo((e.clientX-r.left)*e.currentTarget.width/r.width,(e.clientY-r.top)*e.currentTarget.height/r.height);if(c){c.lineWidth=3;c.lineCap="round";c.strokeStyle="#172033";c.stroke()}setSigned(true)}} onPointerUp={()=>drawing.current=false} onPointerLeave={()=>drawing.current=false}/><button type="button" className="secondaryBtn" onClick={()=>{const c=canvasRef.current;c?.getContext("2d")?.clearRect(0,0,c.width,c.height);setSigned(false)}}>Limpar assinatura</button></div></section>}
  {step===6&&<section className="periodicityPanel"><h3>Identificação e aceite do cliente</h3><p className="technicalNote">Opcional. A assinatura digital/QR existente do responsável técnico permanece preservada.</p><div className="inspectionGrid">{([['name','Nome'],['role','Cargo / função'],['registry','Documento / registro'],['date','Data']] as const).map(([key,label])=><Field label={label} key={key}><input type={key==="date"?"date":"text"} value={data.clientSignature?.[key]||""} onChange={e=>upd("clientSignature",{...emptyInspectionData().clientSignature!,...data.clientSignature,[key]:e.target.value})}/></Field>)}</div></section>}
  {saved&&<p className="formSuccess">Rascunho salvo.</p>}{error&&<p id="inspection-validation-error" ref={errorRef} className="formError inspectionSubmitError" role="alert" tabIndex={-1}>{error}</p>}<div className="formActions"><button type="button" className="secondaryBtn" disabled={step===0||busy} onClick={()=>setStep(x=>x-1)}>Voltar</button>{step<steps.length-1?<button type="button" className="primary" disabled={busy||!selected} onClick={continueFlow}>Continuar <Icon name="arrow"/></button>:<button type="submit" className="primary" disabled={busy||!selected}>{busy?"Concluindo…":"Concluir inspeção"}</button>}</div>
 </form>{deviceTypeIndex!==null&&<div className="modal" role="presentation" onMouseDown={closeDeviceType}><form className="dialog deviceTypeDialog" role="dialog" aria-modal="true" aria-labelledby="device-type-title" onSubmit={createDeviceType} onMouseDown={event=>event.stopPropagation()}><div className="panelHead"><div><small>CATÁLOGO DO TENANT</small><h2 id="device-type-title">Adicionar tipo de dispositivo</h2></div><button type="button" className="close" aria-label="Cancelar cadastro" onClick={closeDeviceType}>×</button></div><label>Nome do novo tipo<input autoFocus required minLength={2} maxLength={120} value={newDeviceType} onChange={event=>{setNewDeviceType(event.target.value);setDeviceTypeError("")}} placeholder="Ex.: Pressostato digital"/></label>{deviceTypeError&&<p className="formError" role="alert">{deviceTypeError}</p>}<div className="dialogActions"><button type="button" className="secondaryBtn" onClick={closeDeviceType}>Cancelar</button><button type="submit" className="primary" disabled={busy}>{busy?"Salvando…":"Salvar tipo"}</button></div></form></div>}</>;
}
